// Synthetics probe: GET announcements and GET preferences through the run's HTTP API.
const synthetics = require('Synthetics');
const log = require('SyntheticsLogger');

// Step names allow letters, digits, hyphens, underscores, periods and spaces only.
const STEPS = [
  ['GET announcements', '/api/announcements'],
  ['GET preferences', '/api/preferences/synthetic-probe'],
];

const expect2xx = async (res) => new Promise((resolve, reject) => {
  let body = '';
  res.on('data', (chunk) => { body += chunk; });
  res.on('end', () => {
    log.info(`status ${res.statusCode} body ${body.slice(0, 200)}`);
    if (res.statusCode < 200 || res.statusCode > 299) {
      reject(new Error(`status ${res.statusCode}`));
    } else {
      resolve();
    }
  });
});

exports.handler = async () => {
  const base = new URL(process.env.API_URL);
  for (const [step, path] of STEPS) {
    await synthetics.executeHttpStep(step, {
      hostname: base.hostname,
      method: 'GET',
      path,
      port: 443,
      protocol: 'https:',
      headers: { 'User-Agent': synthetics.getCanaryUserAgentString() },
    }, expect2xx);
  }
};
